input.command:
python3 -I - <<'EOF'
import re
src=open('formal/Ern/MM02.lean').read()
# find docstrings followed by a declaration
for m in re.finditer(r'/--(.*?)-/\s*\n(\S[^\n]*)', src, re.S):
    doc, decl = m.group(1), m.group(2)
    if 'MM-' not in doc:
        print('NO MM CITE:', decl[:90], '|', doc.strip()[:80])
# declarations without docstring
lines=src.split('\n')
for i,l in enumerate(lines):
    if re.match(r'^(theorem|def|instance|structure|inductive|example|abbrev|noncomputable)', l):
        prev=lines[i-1].strip() if i>0 else ''
        if not prev.endswith('-/'):
            print('NO DOC line',i+1,l[:90])
EOF

